// Bundle the corpus for the site: docs/examples.js.
// usage: node tools/site-examples.js
'use strict';
const fs = require('fs');
const path = require('path');

const root = path.join(__dirname, '..');
const out = [];
for (const dir of ['examples', 'submissions']) {
  for (const f of fs.readdirSync(path.join(root, dir)).sort()) {
    if (!f.endsWith('.sheaf')) continue;
    out.push({ name: f, dir, text: fs.readFileSync(path.join(root, dir, f), 'utf8') });
  }
}
fs.writeFileSync(path.join(root, 'docs', 'examples.js'),
  '// generated by tools/site-examples.js from examples/ and submissions/\n' +
  'var SHEAF_EXAMPLES = ' + JSON.stringify(out, null, 1) + ';\n');
console.log(out.length + ' manuscripts bundled');
